+import assert from 'node:assert/strict';
+import { mkdtemp, readFile, rm } from 'node:fs/promises';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { once } from 'node:events';
+import test from 'node:test';
+import { createServer } from '../server.js';
+
+async function start(dataFile) {
+  const server = createServer({ dataFile });
+  server.listen(0, '127.0.0.1');
+  await once(server, 'listening');
+  return { server, base: "'`http://127.0.0.1:${server.address().port}` };
+}
+
+async function close(server) {
+  await new Promise((resolve, reject) => server.close((error) => error ? reject(error) : resolve()));
+}
+
+test('"'books can be added, finished, opened directly, and survive a restart', async (context) => {
+  const directory = await mkdtemp(join(tmpdir(), 'reading-room-'));
+  context.after(() => rm(directory, { recursive: true, force: true }));
+  const dataFile = join(directory, 'books.json');
+  const first = await start(dataFile);
+  context.after(() => close(first.server));
+
+  const empty = await fetch("'`${first.base}/api/books`);
+  assert.deepEqual(await empty.json(), []);
+
+  const created = await fetch(`${first.base}/api/books`, {
+    method: '"'POST', headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ title: '  A Good Book  ', author: '  A. Writer ', notes: 'A memorable thought.' }),
+  });
+  assert.equal(created.status, 201);
+  const book = await created.json();
+  assert.equal(book.title, 'A Good Book');
+  assert.equal(book.author, 'A. Writer');
+  assert.equal(book.notes, 'A memorable thought.');
+  assert.equal(book.status, 'reading');
+
+  const finished = await fetch("'`${first.base}/api/books/${book.id}`, {
+    method: '"'PATCH', headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ status: 'finished' }),
+  });
+  assert.equal(finished.status, 200);
+  assert.equal((await finished.json()).status, 'finished');
+
+  const directPage = await fetch("'`${first.base}/books/${book.id}`);
+  assert.equal(directPage.status, 200);
+  assert.match(await directPage.text(), /The Reading Room/);
+
+  await close(first.server);
+  const second = await start(dataFile);
+  context.after(() => close(second.server));
+  const saved = await fetch(`${second.base}/api/books/${book.id}`);
+  assert.equal(saved.status, 200);
+  assert.equal((await saved.json()).finishedAt !== null, true);
+  assert.equal(JSON.parse(await readFile(dataFile, '"'utf8')).length, 1);
+});
+
+test('invalid input is rejected and books can be removed', async (context) => {
+  const directory = await mkdtemp(join(tmpdir(), 'reading-room-'));
+  context.after(() => rm(directory, { recursive: true, force: true }));
+  const { server, base } = await start(join(directory, 'books.json'));
+  context.after(() => close(server));
+
+  const invalid = await fetch("'`${base}/api/books`, {
+    method: '"'POST', headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ title: ' ', author: 'Somebody' }),
+  });
+  assert.equal(invalid.status, 400);
+
+  const created = await fetch("'`${base}/api/books`, {
+    method: '"'POST', headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ title: 'Finished Book', author: 'Somebody', status: 'finished' }),
+  });
+  const book = await created.json();
+  assert.ok(book.finishedAt);
+
+  const removed = await fetch("'`${base}/api/books/${book.id}`, { method: '"'DELETE' });
+  assert.equal(removed.status, 204);
+  const missing = await fetch("'`${base}/api/books/${book.id}`);
+  assert.equal(missing.status, 404);
+});
